class Solution {
  public int numberOfSets(int n, int k) {
    final long mod = 1_000_000_007L;
    int top = n + k - 1, choose = 2 * k;
    long[] fact = new long[top + 1], invFact = new long[top + 1];
    fact[0] = 1;
    for (int i = 1; i <= top; i++) fact[i] = fact[i - 1] * i % mod;
    invFact[top] = pow(fact[top], mod - 2, mod);
    for (int i = top; i > 0; i--) invFact[i - 1] = invFact[i] * i % mod;
    return (int) (fact[top] * invFact[choose] % mod * invFact[top - choose] % mod);
  }

  private long pow(long a, long e, long mod) {
    long r = 1;
    while (e > 0) {
      if ((e & 1) == 1) r = r * a % mod;
      a = a * a % mod;
      e >>= 1;
    }
    return r;
  }
}
